#!/usr/bin/env bash
# acceptance — passes:true must name a green test; no removals vs HEAD
set -euo pipefail
[ -d specs ] || { echo "no specs/ directory (no active spec)"; exit 0; }
node -e 'const fs=require("fs"),path=require("path"),{spawnSync}=require("child_process"),specs="specs",dirs=fs.readdirSync(specs).filter(s=>fs.existsSync(path.join(specs,s,"acceptance.json"))),fail=[];if(!dirs.length){console.log("no active spec");process.exit(0)}for(const slug of dirs){const acc=path.join(specs,slug,"acceptance.json"),cur=JSON.parse(fs.readFileSync(acc,"utf8")),entries=Array.isArray(cur)?cur:cur.entries||[],head=spawnSync("git",["show","HEAD:"+acc],{encoding:"utf8"});if(head.status===0&&head.stdout.trim()){try{const prev=JSON.parse(head.stdout),pe=Array.isArray(prev)?prev:prev.entries||[];for(const e of pe){if(!entries.some(x=>x.id===e.id))fail.push(slug+": removed "+e.id)}}catch{}}for(const e of entries){if(!e.passes)continue;if(!e.test){fail.push(slug+"/"+e.id+": no test");continue}const fp=e.test.split(":")[0];if(!fs.existsSync(fp))fail.push(slug+"/"+e.id+": missing "+e.test)}}if(fail.length){console.error(fail.join("\n"));process.exit(1)}console.log("acceptance claims consistent")'
